def recherchedico(l, val, debut=0):
    if len(l) == 0:
        return -1
    pos = len(l) // 2
    if l[pos] == val:
        return debut + pos
    elif l[pos] > val:
        return recherchedico(l[:pos], val, debut=debut)
    else:
        return recherchedico(l[pos+1:], val, debut=debut+pos+1)

def posdico(l, val, debut=0):
    if len(l) == 0:
        return debut
    if len(l) ==1:
        #print("ici",val, debut)
        if val < l[0]:
            return debut
        elif val == l[0]:
            return debut
        else:
            return debut+1
    pos = len(l) // 2
    if l[pos] == val:
        return pos + debut
    elif l[pos] > val:
        return posdico(l[:pos], val, debut=debut)
    else:
        return posdico(l[pos+1:], val, debut=debut+pos+1)

def insert(l, val):
    if len(l) == 0:
        return [val]
    pos = posdico(l,val)
    #print(l, val, pos)
    return l[:pos]+[val]+l[pos:]

def delete(l, val):
    pos = recherchedico(l, val)
    if (pos == -1):
        return l
    else:
        return l[:pos] +l[pos+1:]
